parameters.jsCode:
// === PARSER SCORING DE LEAD ===
const input = $input.first().json;

let responseText = '';
if (input.output) {
  for (const block of input.output) {
    if (block.content) {
      for (const content of block.content) {
        if (content.type === 'output_text' && content.text) {
          responseText = content.text;
          break;
        }
      }
    }
    if (responseText) break;
  }
} else if (input.message?.content) {
  responseText = input.message.content;
} else if (input.text) {
  responseText = input.text;
}

responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let scoring;
try {
  scoring = JSON.parse(responseText);
} catch (e) {
  scoring = {
    score: 50,
    categoria: 'tibio',
    razon: 'No se pudo evaluar correctamente',
    productos_interes: [],
    es_empresa: false,
    accion_recomendada: 'secuencia nurturing'
  };
}

// Recuperar datos originales
const original = $('Entrada desde Orquestador').first().json;

const leadId = 'LEAD-' + Date.now().toString().slice(-6);
const now = new Date().toISOString().split('T')[0];

return {
  json: {
    lead_id: leadId,
    fecha_captura: now,
    nombre: original.sender_name,
    canal: original.channel,
    sender_id: original.sender_id,
    chat_id: original.chat_id,
    mensaje_original: original.message_text,
    score: scoring.score,
    categoria: scoring.categoria,
    razon: scoring.razon,
    productos_interes: scoring.productos_interes.join(', '),
    es_empresa: scoring.es_empresa,
    accion_recomendada: scoring.accion_recomendada
  }
};

